import pandas as pd
from catboost import CatBoostClassifier

def fit(train: pd.DataFrame, target: str, seed: int) -> object:
    X = train.drop(columns=[target])
    y = train[target]
    X_new = X.copy()
    # Log transforms for skewed positive features
    for col in ['creditscore', 'age', 'balance', 'estimatedsalary']:
        if col in X_new.columns:
            X_new[f'log_{col}'] = np.log1p(X_new[col])
    # Square root transforms
    for col in ['creditscore', 'age', 'balance', 'estimatedsalary']:
        if col in X_new.columns:
            X_new[f'sqrt_{col}'] = np.sqrt(X_new[col])
    # Ratio features
    X_new['balance_to_salary'] = X_new['balance'] / (X_new['estimatedsalary'] + 1e-5)
    X_new['creditscore_to_age'] = X_new['creditscore'] / (X_new['age'] + 1e-5)
    X_new['balance_to_creditscore'] = X_new['balance'] / (X_new['creditscore'] + 1e-5)
    # Product features
    X_new['creditscore_balance'] = X_new['creditscore'] * X_new['balance']
    X_new['age_balance'] = X_new['age'] * X_new['balance']
    X_new['tenure_numofproducts'] = X_new['tenure'] * X_new['numofproducts']
    X_new['creditscore_age'] = X_new['creditscore'] * X_new['age']
    # Drop surname
    if 'surname' in X_new.columns:
        X_new = X_new.drop(columns=['surname'])
    # TF-IDF mean
    tfidf_cols = [f'surname_tfidf_{i}' for i in range(5)]
    if all(col in X_new.columns for col in tfidf_cols):
        X_new['surname_tfidf_mean'] = X_new[tfidf_cols].mean(axis=1)
    # Country-gender interactions (already one-hot)
    countries = ['france', 'germany', 'spain']
    genders = ['female', 'male']
    for c in countries:
        for g in genders:
            if c in X_new.columns and g in X_new.columns:
                X_new[f'{c}_{g}'] = X_new[c] * X_new[g]
    # Country * card/active
    for c in countries:
        if c in X_new.columns:
            if 'hascrcard' in X_new.columns:
                X_new[f'{c}_hascrcard'] = X_new[c] * X_new['hascrcard']
            if 'isactivemember' in X_new.columns:
                X_new[f'{c}_isactivemember'] = X_new[c] * X_new['isactivemember']
    # Gender * card/active
    for g in genders:
        if g in X_new.columns:
            if 'hascrcard' in X_new.columns:
                X_new[f'{g}_hascrcard'] = X_new[g] * X_new['hascrcard']
            if 'isactivemember' in X_new.columns:
                X_new[f'{g}_isactivemember'] = X_new[g] * X_new['isactivemember']
    # Numofproducts interactions
    if 'numofproducts' in X_new.columns:
        if 'hascrcard' in X_new.columns:
            X_new['numofproducts_hascrcard'] = X_new['numofproducts'] * X_new['hascrcard']
        if 'isactivemember' in X_new.columns:
            X_new['numofproducts_isactivemember'] = X_new['numofproducts'] * X_new['isactivemember']
    model = CatBoostClassifier(
        iterations=1000,
        learning_rate=0.01,
        depth=8,
        l2_leaf_reg=3,
        loss_function='Logloss',
        random_seed=seed,
        verbose=False,
        subsample=0.9,
        rsm=0.9
    )
    model.fit(X_new, y)
    return model

